package com.shiphappens.logistics.controller;
import com.shiphappens.logistics.dto.Requests; import com.shiphappens.logistics.entity.*; import com.shiphappens.logistics.entity.Statuses.ShipmentStatus; import com.shiphappens.logistics.service.LogisticsService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/shipments") public class ShipmentController { private final LogisticsService service; public ShipmentController(LogisticsService service){this.service=service;} @GetMapping public List<Shipment> list(@RequestParam(required=false) ShipmentStatus status){return service.listShipments(status);}@GetMapping("/{id}") public Shipment get(@PathVariable Long id){return service.findShipment(id);}@PatchMapping("/{id}/status") public Shipment status(@PathVariable Long id,@Valid @RequestBody Requests.ShipmentStatus request){return service.updateShipment(id,request);}@GetMapping("/{id}/tracking") public List<TrackingEvent> tracking(@PathVariable Long id){return service.tracking(id);} }
